Database.Load:
// NOTICE: contract attribute external="true" is required when using external SQL queries.

var RecordTypeName = "";

if (Utils.isDefined(jsonQuery.recordTypeName)) {
  RecordTypeName = Utils.convertForDBParam(jsonQuery.recordTypeName, "TEXT");
}


var sqlParams = { RecordTypeName };

var sqlStmt = "";
sqlStmt += " SELECT";
sqlStmt += "   Account.Id AS pKey,";
sqlStmt += "   Account.Name AS wholesalerName,";
sqlStmt += "   CASE WHEN Account.Clearing_House_Participant__c = 1 THEN 'OverduePromotion' ELSE 'EmptyImage' END as wholesalerClear,";
sqlStmt += "   RT.DeveloperName AS RecordTypeName";
sqlStmt += " FROM";
sqlStmt += "   Account";
sqlStmt += "   LEFT JOIN RecordType AS RT ON RT.Id = Account.RecordTypeId";
sqlStmt += " WHERE";
sqlStmt += "   RecordTypeName = #RecordTypeName#";


return Utils.replaceMacrosParam(sqlStmt, sqlParams);
